ALTER TABLE animals ADD COLUMN IF NOT EXISTS foster_available_since TIMESTAMPTZ;
CREATE INDEX IF NOT EXISTS idx_animals_foster_available_since ON animals(foster_available_since) WHERE foster_available_since IS NOT NULL;
CREATE TABLE IF NOT EXISTS foster_applications (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), animal_id UUID NOT NULL REFERENCES animals(id) ON DELETE CASCADE, welfare_group_id UUID NOT NULL REFERENCES welfare_orgs(id) ON DELETE CASCADE, applicant_user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE, message TEXT NOT NULL, availability TEXT NOT NULL, experience TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'pending_review' CHECK(status IN ('pending_review','approved','rejected','withdrawn','active','completed')), review_notes TEXT, reviewed_by_user_id UUID REFERENCES users(id) ON DELETE SET NULL, reviewed_at TIMESTAMPTZ, foster_home_id UUID REFERENCES foster_homes(id) ON DELETE SET NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS idx_foster_applications_org_status ON foster_applications(welfare_group_id,status,created_at DESC);
CREATE INDEX IF NOT EXISTS idx_foster_applications_applicant ON foster_applications(applicant_user_id,created_at DESC);
CREATE UNIQUE INDEX IF NOT EXISTS idx_foster_applications_one_active_per_user_animal ON foster_applications(animal_id,applicant_user_id) WHERE status IN ('pending_review','approved','active');
ALTER TABLE foster_applications ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE foster_applications FROM anon,authenticated;
GRANT ALL ON TABLE foster_applications TO service_role;
CREATE OR REPLACE FUNCTION close_animal_listing_after_adoption() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.status='adopted' AND OLD.status IS DISTINCT FROM NEW.status THEN UPDATE animals SET status='adopted',adoptable_since=NULL,updated_at=NOW() WHERE id=NEW.animal_id; END IF; RETURN NEW; END; $$;
DROP TRIGGER IF EXISTS trg_close_animal_listing_after_adoption ON adoption_applications;
CREATE TRIGGER trg_close_animal_listing_after_adoption AFTER UPDATE OF status ON adoption_applications FOR EACH ROW EXECUTE FUNCTION close_animal_listing_after_adoption();
